                <div class="form-field">
                  <fieldset aria-describedby="notification-preference-help notification-preference-error">
                    <legend id="notification-preference-title">How do you prefer to receive notifications?</legend>
                    <p class="field-help" id="notification-preference-help">Select a single answer before submitting.</p>
