                    </div>
                    <p class="error-message" id="notification-preference-error" aria-live="assertive"></p>
                  </fieldset>
                </div>

                <div class="submit-row">
                  <button class="submit-button" type="submit">Submit</button>
                </div>
              </form>
            </section>
